<?php

declare(strict_types=1);

namespace Domain\Comments\Api;

use App\Contracts\Domains\ApiSender;
use App\Support\CallKey;
use Domain\Comments\Data\CommentList;

/**
 * The API of Comments, generated by php artisan journal:api; run it again instead of editing.
 */
final readonly class CommentApi
{
    public function __construct(private ApiSender $sender) {}

    public function listComments(
        string $target,
        string|null $after = null,
        int|null $perPage = null,
    ): CommentList {
        return $this->sender->send(ListCommentsPayload::from([
            'target' => $target,
            'after' => $after,
            'perPage' => $perPage,
        ]));
    }

    public function locateComment(
        string $target,
        string $comment,
        int|null $firstLine = null,
        int|null $lastLine = null,
    ): CommentLocated {
        return $this->sender->send(LocateCommentPayload::from([
            'target' => $target,
            'comment' => $comment,
            'firstLine' => $firstLine,
            'lastLine' => $lastLine,
        ]));
    }

    public function postComment(
        string $target,
        string $body,
        string $submissionKey,
        CallKey $requestKey = new CallKey(),
        CommentPlace|null $place = null,
    ): CommentPosted {
        return $this->sender->send(PostCommentPayload::from([
            'target' => $target,
            'body' => $body,
            'submissionKey' => $submissionKey,
            'requestKey' => $requestKey,
            'place' => $place,
        ]));
    }
}
